SELECT cp.cp_id, cp.project_id, cp.cp_title, cp.cp_type AS category, cp.cp_price, cp.cp_amount, cp.product_certificate, cp.vintage_year, cp.cp_detail, COALESCE(f.thumbnail_url, '/resources/img/carbon_sample.jpg') AS thumbnailUrl FROM carbon_products cp INNER JOIN projects p ON cp.project_id = p.project_id INNER JOIN farms f ON p.farm_id = f.farm_id WHERE cp.project_id IN ( SELECT project_id FROM tokens WHERE token_id IN
#{id}
) ORDER BY cp.cp_id DESC

SELECT cp.cp_id, cp.project_id, cp.cp_title, cp.cp_type AS category, cp.cp_price, cp.cp_amount, cp.product_certificate, cp.vintage_year, cp.cp_detail, COALESCE(f.thumbnail_url, '/resources/img/carbon_sample.jpg') AS thumbnailUrl FROM carbon_products cp INNER JOIN projects p ON cp.project_id = p.project_id INNER JOIN farms f ON p.farm_id = f.farm_id
AND cp.cp_type = #{category}
AND cp.project_id IN ( SELECT project_id FROM tokens WHERE token_id IN
#{id}
)
ORDER BY cp.cp_id DESC

SELECT ucl_id
FROM user_certificate_links
WHERE user_id = #{userId}

SELECT token_id
FROM tokens
WHERE project_id = #{projectId}

SELECT total_supply
FROM tokens
WHERE project_id = #{projectId}

SELECT total_supply
FROM tokens
WHERE token_id = #{tokenId}

SELECT cp_title
FROM carbon_products
WHERE cp_id = #{cpId}

SELECT cp_amount
FROM carbon_products
WHERE cp_id = #{cpId}

SELECT token_id
FROM carbon_snapshot_history
WHERE snapshot_id = #{snapshotId}
AND user_id = #{userId}
AND token_balance > 0
